#include <bits/stdc++.h>
using namespace std;const long long P=1e9;const int N=85;long long a[N][N];int id[10][10];char s[10][10];int main(){ios::sync_with_stdio(0);cin.tie(0);int n,m,k=0;cin>>n>>m;for(int i=0;i<n;i++){cin>>s[i];for(int j=0;j<m;j++)if(s[i][j]=='.')id[i][j]=k++;else id[i][j]=-1;}if(k<2)return cout<<k<<'\n',0;for(int i=0;i<n;i++)for(int j=0;j<m;j++)if(id[i][j]>=0){if(i+1<n&&id[i+1][j]>=0){int x=id[i][j],y=id[i+1][j];a[x][x]++;a[y][y]++;a[x][y]=a[y][x]=P-1;}if(j+1<m&&id[i][j+1]>=0){int x=id[i][j],y=id[i][j+1];a[x][x]++;a[y][y]++;a[x][y]=a[y][x]=P-1;}}k--;long long z=1;for(int i=0;i<k;i++)for(int j=i+1;j<k;j++)while(a[j][i]){long long q=a[i][i]/a[j][i];for(int x=i;x<k;x++)a[i][x]=(a[i][x]-q*a[j][x]%P+P)%P;for(int x=i;x<k;x++)swap(a[i][x],a[j][x]);z=P-z;}for(int i=0;i<k;i++)z=z*a[i][i]%P;cout<<z<<'\n';}
